local a=require("nav.waypoints")local b={}b.DISK_FILE="eh2_nav_wpt.tbl"function b.diskPath(c)return"/"..tostring(c).."/"..b.DISK_FILE end;function b.isValidStore(d)return type(d)=="table"and type(d.waypoints)=="table"end;function b.export(e,c,f)if not c then return false,"no disk"end;return f.write(b.diskPath(c),textutils.serialise(e))and true or false end;function b.scan(c,f)if not c then return{hasDisk=false,valid=false}end;local g=f.read(b.diskPath(c))if g==nil then return{hasDisk=false,valid=false}end;local h,i=pcall(textutils.unserialise,g)return{hasDisk=true,valid=h and b.isValidStore(i)}end;function b.import(e,c,f)if not c then return nil,"no disk"end;local g=f.read(b.diskPath(c))if g==nil then return nil,"no nav file on disk"end;local h,i=pcall(textutils.unserialise,g)if not h or not b.isValidStore(i)then return nil,"not a nav store"end;a.mergeWpts(e,i.waypoints)a.mergeRoutes(e,i.routes or{})return e end;function b.clean(c,f)if not c then return false end;f.delete(b.diskPath(c))return true end;return b